from app import config
from app.config import RESULTS_COLUMNS, RETRIEVAL_SETTINGS, load_settings


def test_results_columns_match_brief_exactly():
    assert ",".join(RESULTS_COLUMNS) == (
        "request_id,scenario,source,start_time,first_token_ms,total_ms,status,retries,"
        "tokens_in,tokens_out,retrieval_setting,answer_grade"
    )


def test_api_key_never_in_repr_or_public_dict():
    s = load_settings(groq_api_key="gsk_secret_for_test")
    assert "gsk_secret_for_test" not in repr(s)
    assert "groq_api_key" not in s.public_dict()


def test_at_least_three_retrieval_settings_that_differ():
    assert len(RETRIEVAL_SETTINGS) >= 3
    sizes = {s.piece_tokens for s in RETRIEVAL_SETTINGS.values()}
    assert len(sizes) >= 3
    assert config.DEFAULT_RETRIEVAL in RETRIEVAL_SETTINGS
    for s in RETRIEVAL_SETTINGS.values():
        assert s.fetch >= s.pieces
        assert s.overlap_tokens < s.piece_tokens

"""Provider-neutral types for one model call. Retrying is NOT done here: one call = one HTTP
attempt, so every retry is visible to (and counted by) the retry manager."""
from __future__ import annotations

import re
from dataclasses import dataclass, field

# Error kinds. Only the retry manager decides what to do with them.
RATE_LIMITED = "rate_limited"
TIMEOUT_BEFORE_FIRST_TOKEN = "timeout_before_first_token"
TIMEOUT_AFTER_FIRST_TOKEN = "timeout_after_first_token"
CONNECTION = "connection"
SERVER = "server"          # 5xx or an error event inside the stream
CLIENT = "client"          # 4xx other than 429: our request is wrong, retrying cannot help

_DURATION_PART = re.compile(r"(\d+(?:\.\d+)?)(ms|h|m|s)")
_LIMIT_KIND = re.compile(r"\((RPM|TPM|RPD|TPD|ITPM|OTPM)\)")


def parse_duration_s(value: str | None) -> float | None:
    """Parse Groq reset durations such as '7.66s', '2m59.56s', '1h2m3s', '120ms'."""
    if not value:
        return None
    value = value.strip()
    try:
        return float(value)
    except ValueError:
        pass
    parts = _DURATION_PART.findall(value)
    if not parts or "".join(n + u for n, u in parts) != value:
        return None
    scale = {"h": 3600.0, "m": 60.0, "s": 1.0, "ms": 0.001}
    return sum(float(n) * scale[u] for n, u in parts)


def limit_kind_from_message(message: str | None) -> str | None:
    """Groq 429 messages name the limit, e.g. '... on tokens per minute (TPM): Limit 8000 ...'."""
    if not message:
        return None
    m = _LIMIT_KIND.search(message)
    return m.group(1) if m else None


@dataclass
class RateLimitInfo:
    """Snapshot of Groq's rate-limit headers. Per Groq docs, *-requests refer to the per-DAY
    request limit and *-tokens refer to the per-MINUTE token limit."""
    limit_requests_day: int | None = None
    remaining_requests_day: int | None = None
    reset_requests_day_s: float | None = None
    limit_tokens_minute: int | None = None
    remaining_tokens_minute: int | None = None
    reset_tokens_minute_s: float | None = None
    retry_after_s: float | None = None

    @classmethod
    def from_headers(cls, headers) -> "RateLimitInfo":
        def _int(name):
            v = headers.get(name)
            try:
                return int(float(v)) if v is not None else None
            except ValueError:
                return None
        return cls(
            limit_requests_day=_int("x-ratelimit-limit-requests"),
            remaining_requests_day=_int("x-ratelimit-remaining-requests"),
            reset_requests_day_s=parse_duration_s(headers.get("x-ratelimit-reset-requests")),
            limit_tokens_minute=_int("x-ratelimit-limit-tokens"),
            remaining_tokens_minute=_int("x-ratelimit-remaining-tokens"),
            reset_tokens_minute_s=parse_duration_s(headers.get("x-ratelimit-reset-tokens")),
            retry_after_s=parse_duration_s(headers.get("retry-after")),
        )


@dataclass
class CallResult:
    """Everything measured about one HTTP attempt. Times are seconds on the monotonic clock;
    `t_start` is when the request was handed to the HTTP client."""
    source: str
    model: str
    t_start: float
    t_headers: float | None = None          # response headers received
    t_first_reasoning: float | None = None  # first reasoning delta (gpt-oss thinks before answering)
    t_first_token: float | None = None      # first *content* delta
    t_end: float | None = None
    status_code: int | None = None
    ok: bool = False
    error_kind: str | None = None
    error_message: str | None = None
    limit_kind: str | None = None           # RPM / TPM / RPD / TPD when a 429 names it
    content: str = ""
    reasoning_chars: int = 0
    finish_reason: str | None = None
    tokens_in: int | None = None
    tokens_out: int | None = None
    reasoning_tokens: int | None = None
    rate_limit: RateLimitInfo = field(default_factory=RateLimitInfo)
    raw_headers: dict = field(default_factory=dict)

    @property
    def first_token_ms(self) -> float | None:
        return None if self.t_first_token is None else (self.t_first_token - self.t_start) * 1000

    @property
    def total_ms(self) -> float | None:
        return None if self.t_end is None else (self.t_end - self.t_start) * 1000

    def to_log(self) -> dict:
        d = {k: v for k, v in self.__dict__.items() if k not in ("rate_limit", "content")}
        d["rate_limit"] = self.rate_limit.__dict__
        d["content_chars"] = len(self.content)
        d["first_token_ms"] = self.first_token_ms
        d["total_ms"] = self.total_ms
        return d


class ProviderError(Exception):
    def __init__(self, result: CallResult):
        super().__init__(f"{result.error_kind}: {result.error_message}")
        self.result = result

    @property
    def kind(self) -> str:
        return self.result.error_kind or SERVER

"""One client for any OpenAI-compatible chat endpoint: Groq (source='real') and our stand-in
(source='stand-in'). Uses raw httpx so that every attempt, header and timing is visible."""
from __future__ import annotations

import asyncio
import json
import time
from datetime import datetime, timezone
from pathlib import Path

import httpx

from app.config import RESULTS_DIR, Settings
from app.providers.base import (
    CLIENT, CONNECTION, RATE_LIMITED, SERVER, TIMEOUT_AFTER_FIRST_TOKEN,
    TIMEOUT_BEFORE_FIRST_TOKEN, CallResult, ProviderError, RateLimitInfo, limit_kind_from_message,
)

SPEND_LEDGER = RESULTS_DIR / "groq_spend.jsonl"


class StreamCall:
    """`async for delta in call` yields answer text; `call.result` holds the measurements,
    also after a ProviderError (which carries the same result object)."""

    def __init__(self, provider: "OpenAICompatProvider", payload: dict,
                 timeout_s: float, first_token_timeout_s: float | None):
        self._p = provider
        self._payload = payload
        self._timeout_s = timeout_s
        self._ft_timeout_s = first_token_timeout_s
        self.result = CallResult(source=provider.source, model=payload["model"], t_start=0.0)

    def __aiter__(self):
        return self._run()

    def _wait_budget(self, deadline: float, ft_deadline: float | None) -> float:
        now = time.monotonic()
        limit = deadline
        if ft_deadline is not None and self.result.t_first_token is None:
            limit = min(limit, ft_deadline)
        return limit - now

    async def _run(self):
        r = self.result
        r.t_start = time.monotonic()
        deadline = r.t_start + self._timeout_s
        ft_deadline = r.t_start + self._ft_timeout_s if self._ft_timeout_s else None
        resp = None
        try:
            req = self._p.client.build_request("POST", "/chat/completions", json=self._payload)
            budget = self._wait_budget(deadline, ft_deadline)
            if budget <= 0:
                raise asyncio.TimeoutError
            resp = await asyncio.wait_for(self._p.client.send(req, stream=True), budget)
            r.t_headers = time.monotonic()
            self._p._record_headers(r, resp)
            if resp.status_code != 200:
                body = (await resp.aread()).decode("utf-8", "replace")
                self._p._classify_http_error(r, resp.status_code, body)
                raise ProviderError(r)

            lines = resp.aiter_lines()
            while True:
                budget = self._wait_budget(deadline, ft_deadline)
                if budget <= 0:
                    raise asyncio.TimeoutError
                try:
                    line = await asyncio.wait_for(lines.__anext__(), budget)
                except StopAsyncIteration:
                    break
                if not line.startswith("data:"):
                    continue
                data = line[5:].strip()
                if data == "[DONE]":
                    break
                chunk = json.loads(data)
                if "error" in chunk:
                    r.error_kind = SERVER
                    r.error_message = json.dumps(chunk["error"])[:500]
                    raise ProviderError(r)
                usage = chunk.get("usage") or (chunk.get("x_groq") or {}).get("usage")
                if usage:
                    self._p._record_usage(r, usage)
                for choice in chunk.get("choices") or []:
                    delta = choice.get("delta") or {}
                    if delta.get("reasoning"):
                        if r.t_first_reasoning is None:
                            r.t_first_reasoning = time.monotonic()
                        r.reasoning_chars += len(delta["reasoning"])
                    text = delta.get("content")
                    if text:
                        if r.t_first_token is None:
                            r.t_first_token = time.monotonic()
                        r.content += text
                        yield text
                    if choice.get("finish_reason"):
                        r.finish_reason = choice["finish_reason"]
            r.ok = True
        except ProviderError:
            raise
        except (asyncio.TimeoutError, httpx.TimeoutException) as e:
            r.error_kind = TIMEOUT_BEFORE_FIRST_TOKEN if r.t_first_token is None else TIMEOUT_AFTER_FIRST_TOKEN
            r.error_message = type(e).__name__
            raise ProviderError(r) from None
        except (httpx.TransportError, json.JSONDecodeError) as e:
            r.error_kind = CONNECTION
            r.error_message = f"{type(e).__name__}: {e}"[:500]
            raise ProviderError(r) from None
        finally:
            r.t_end = time.monotonic()
            if resp is not None:
                await resp.aclose()
            self._p._ledger(r)


class OpenAICompatProvider:
    def __init__(self, base_url: str, api_key: str, model: str, source: str,
                 settings: Settings, transport: httpx.AsyncBaseTransport | None = None,
                 ledger_path: Path | None = None):
        if source not in ("real", "stand-in"):
            raise ValueError(source)
        if source == "real" and not api_key:
            raise RuntimeError("GROQ_API_KEY is not set (put it in .env)")
        self.source = source
        self.model = model
        self.settings = settings
        self.ledger_path = ledger_path if ledger_path is not None else (SPEND_LEDGER if source == "real" else None)
        self.client = httpx.AsyncClient(
            base_url=base_url,
            headers={"Authorization": f"Bearer {api_key or 'stand-in'}"},
            timeout=httpx.Timeout(connect=settings.provider_connect_timeout_s, read=None, write=10.0, pool=None),
            limits=httpx.Limits(max_connections=200, max_keepalive_connections=50),
            transport=transport,
        )

    @classmethod
    def groq(cls, settings: Settings, **kw) -> "OpenAICompatProvider":
        return cls(settings.groq_base_url, settings.groq_api_key, settings.model, "real", settings, **kw)

    @classmethod
    def standin(cls, settings: Settings, **kw) -> "OpenAICompatProvider":
        return cls(settings.standin_base_url, "", settings.model, "stand-in", settings, **kw)

    async def aclose(self):
        await self.client.aclose()

    def build_payload(self, messages: list[dict], max_tokens: int, stream: bool,
                      temperature: float = 0.2) -> dict:
        payload = {
            "model": self.model,
            "messages": messages,
            "stream": stream,
            "max_completion_tokens": max_tokens,
            "temperature": temperature,
        }
        if self.model.startswith("openai/gpt-oss"):
            payload["reasoning_effort"] = self.settings.reasoning_effort
            payload["include_reasoning"] = True
        return payload

    def stream_chat(self, messages: list[dict], *, max_tokens: int, timeout_s: float,
                    first_token_timeout_s: float | None = None, temperature: float = 0.2) -> StreamCall:
        return StreamCall(self, self.build_payload(messages, max_tokens, True, temperature),
                          timeout_s, first_token_timeout_s)

    async def complete(self, messages: list[dict], *, max_tokens: int, timeout_s: float,
                       temperature: float = 0.2) -> CallResult:
        """Non-streaming call. For consistency with streaming, first-token time = time the full
        body arrived (the user cannot see anything earlier)."""
        r = CallResult(source=self.source, model=self.model, t_start=time.monotonic())
        try:
            resp = await asyncio.wait_for(
                self.client.post("/chat/completions",
                                 json=self.build_payload(messages, max_tokens, False, temperature)),
                timeout_s)
            r.t_headers = time.monotonic()
            self._record_headers(r, resp)
            if resp.status_code != 200:
                self._classify_http_error(r, resp.status_code, resp.text)
                raise ProviderError(r)
            body = resp.json()
            choice = (body.get("choices") or [{}])[0]
            msg = choice.get("message") or {}
            r.content = msg.get("content") or ""
            r.reasoning_chars = len(msg.get("reasoning") or "")
            r.finish_reason = choice.get("finish_reason")
            if body.get("usage"):
                self._record_usage(r, body["usage"])
            r.t_first_token = time.monotonic()
            r.ok = True
            return r
        except ProviderError:
            raise
        except (asyncio.TimeoutError, httpx.TimeoutException) as e:
            r.error_kind, r.error_message = TIMEOUT_BEFORE_FIRST_TOKEN, type(e).__name__
            raise ProviderError(r) from None
        except (httpx.TransportError, ValueError) as e:
            r.error_kind, r.error_message = CONNECTION, f"{type(e).__name__}: {e}"[:500]
            raise ProviderError(r) from None
        finally:
            r.t_end = time.monotonic()
            self._ledger(r)

    # --- helpers -------------------------------------------------------------------------
    @staticmethod
    def _record_headers(r: CallResult, resp: httpx.Response):
        r.status_code = resp.status_code
        r.raw_headers = {k: v for k, v in resp.headers.items() if k.lower() not in ("set-cookie",)}
        r.rate_limit = RateLimitInfo.from_headers(resp.headers)

    @staticmethod
    def _record_usage(r: CallResult, usage: dict):
        r.tokens_in = usage.get("prompt_tokens")
        r.tokens_out = usage.get("completion_tokens")
        details = usage.get("completion_tokens_details") or {}
        r.reasoning_tokens = details.get("reasoning_tokens")

    @staticmethod
    def _classify_http_error(r: CallResult, status: int, body: str):
        message = body
        try:
            message = json.loads(body).get("error", {}).get("message", body)
        except (ValueError, AttributeError):
            pass
        r.error_message = str(message)[:1000]
        if status == 429:
            r.error_kind = RATE_LIMITED
            r.limit_kind = limit_kind_from_message(r.error_message)
        elif status >= 500 or status == 498:  # 498 = Groq flex-tier capacity exceeded
            r.error_kind = SERVER
        else:
            r.error_kind = CLIENT

    def _ledger(self, r: CallResult):
        if self.ledger_path is None:
            return
        self.ledger_path.parent.mkdir(parents=True, exist_ok=True)
        with self.ledger_path.open("a", encoding="utf-8") as f:
            f.write(json.dumps({
                "utc": datetime.now(timezone.utc).isoformat(), "model": r.model,
                "status_code": r.status_code, "error_kind": r.error_kind,
                "tokens_in": r.tokens_in, "tokens_out": r.tokens_out,
            }) + "\n")

"""Summarize the real-Groq probe logs into the numbers used for Table 1 and simulator calibration.

    python -m experiments.analyze_probes          # prints a summary, writes results/real_probe/summary.json
"""
from __future__ import annotations

import json
from collections import defaultdict
from datetime import datetime

from app.config import RESULTS_DIR
from app.evaluation.stats import percentile

PROBE_DIR = RESULTS_DIR / "real_probe"


def load(prefix: str) -> list[list[dict]]:
    runs = []
    for path in sorted(PROBE_DIR.glob(f"{prefix}_*.jsonl")):
        runs.append([json.loads(line) for line in path.read_text().splitlines() if line.strip()])
    return runs


def ms(row, key):
    return None if row.get(key) is None else (row[key] - row["t_start"]) * 1000


def utc(row) -> datetime:
    return datetime.fromisoformat(row["utc"])


def dist(values) -> dict:
    v = [x for x in values if x is not None]
    if not v:
        return {"n": 0}
    return {"n": len(v), "min": min(v), "p50": percentile(v, 50), "p95": percentile(v, 95),
            "max": max(v), "mean": sum(v) / len(v)}


def fmt(d: dict) -> str:
    if not d.get("n"):
        return "n=0"
    return (f"n={d['n']} min={d['min']:.0f} p50={d['p50']:.0f} p95={d['p95']:.0f} "
            f"max={d['max']:.0f} mean={d['mean']:.0f}")


def latency_summary(runs) -> dict:
    by_size = defaultdict(list)
    for run in runs:
        for r in run:
            if r["ok"]:
                by_size[r["prompt_size_target"]].append(r)
    out = {}
    for size, rows in sorted(by_size.items()):
        gen_tps = [r["tokens_out"] / ((r["t_end"] - r["t_first_reasoning"]) or 1e-9)
                   for r in rows if r.get("t_first_reasoning") and r.get("tokens_out")]
        out[size] = {
            "tokens_in": dist(r["tokens_in"] for r in rows),
            "tokens_out": dist(r["tokens_out"] for r in rows),
            "reasoning_tokens": dist(r.get("reasoning_tokens") for r in rows),
            "headers_ms": dist(ms(r, "t_headers") for r in rows),
            "first_reasoning_ms": dist(ms(r, "t_first_reasoning") for r in rows),
            "first_token_ms": dist(ms(r, "t_first_token") for r in rows),
            "total_ms": dist(ms(r, "t_end") for r in rows),
            "after_first_token_ms": dist((r["t_end"] - r["t_first_token"]) * 1000
                                         for r in rows if r.get("t_first_token")),
            "gen_tokens_per_s": dist(gen_tps),
        }
    return out


def burst_summary(runs) -> list[dict]:
    """For rpm/tpm runs: how many were accepted before the first 429, over what time, and recovery."""
    out = []
    for run in runs:
        burst = [r for r in run if r.get("phase") == "burst"]
        first_429 = next((r for r in burst if r["status_code"] == 429), None)
        accepted = [r for r in burst if r["status_code"] == 200]
        rec = next((r for r in run if r.get("phase") == "recovery" and r["ok"]), None)
        out.append({
            "file_first_utc": run[0]["utc"],
            "accepted_before_429": len(accepted) if first_429 else None,
            "accepted_span_s": (utc(accepted[-1]) - utc(accepted[0])).total_seconds() if accepted else None,
            "tokens_accepted": sum((r["tokens_in"] or 0) + (r["tokens_out"] or 0) for r in accepted),
            "first_429_message": first_429["error_message"] if first_429 else None,
            "retry_after_values": sorted({r["rate_limit"]["retry_after_s"] for r in run
                                          if r["status_code"] == 429}),
            "remaining_tokens_on_429": first_429["rate_limit"]["remaining_tokens_minute"] if first_429 else None,
            "recovery_s_after_first_429": rec["since_first_429_s"] if rec else None,
            "polls_before_recovery": sum(1 for r in run if r.get("phase") == "recovery" and not r["ok"]),
            "429_latency_ms": dist(ms(r, "t_end") for r in run if r["status_code"] == 429),
            "remaining_tokens_trajectory": [r["rate_limit"]["remaining_tokens_minute"] for r in run],
        })
    return out


def concurrency_summary(runs) -> list[dict]:
    out = []
    for run in runs:
        t0 = min(r["t_start"] for r in run)
        out.append({
            "n": len(run),
            "ok": sum(r["ok"] for r in run),
            "start_spread_ms": (max(r["t_start"] for r in run) - t0) * 1000,
            "headers_ms": dist(ms(r, "t_headers") for r in run),
            "total_ms": dist(ms(r, "t_end") for r in run),
            "remaining_requests_day_seen": [r["rate_limit"]["remaining_requests_day"] for r in run],
        })
    return out


def rpd_refill_check() -> dict:
    """Compare the daily-request header with our own ledger. If the budget refills continuously at
    1000/86400 s, then used_by_header ~= successful_requests - elapsed_s / 86.4."""
    rows = []
    for prefix in ("smoke", "concurrency", "rpm", "tpm", "latency"):
        for run in load(prefix):
            rows += [r for r in run if r["status_code"] == 200]
    rows.sort(key=utc)
    if len(rows) < 2:
        return {}
    first, last = rows[0], rows[-1]
    elapsed = (utc(last) - utc(first)).total_seconds()
    limit = last["rate_limit"]["limit_requests_day"]
    used_by_header = limit - last["rate_limit"]["remaining_requests_day"]
    return {
        "successful_requests_logged": len(rows),
        "elapsed_s": elapsed,
        "used_according_to_header": used_by_header,
        "predicted_if_continuous_refill": len(rows) - elapsed / (86400 / limit),
        "predicted_if_no_refill": len(rows),
        "rejected_429_consumed_daily_requests": None,  # filled in from rpm runs below
    }


def main():
    summary = {
        "latency": latency_summary(load("latency")),
        "rpm": burst_summary(load("rpm")),
        "tpm": burst_summary(load("tpm")),
        "concurrency": concurrency_summary(load("concurrency")),
        "rpd_refill": rpd_refill_check(),
    }
    for run in load("rpm"):
        r429 = [r for r in run if r["status_code"] == 429]
        if r429:
            before = [r for r in run if r["status_code"] == 200 and utc(r) < utc(r429[0])][-1]
            after = next(r for r in run if r["status_code"] == 200 and utc(r) > utc(r429[-1]))
            summary["rpd_refill"]["rejected_429_consumed_daily_requests"] = (
                before["rate_limit"]["remaining_requests_day"] - after["rate_limit"]["remaining_requests_day"] - 1)

    print("== latency by prompt size (ms) ==")
    for size, d in summary["latency"].items():
        print(f"-- target {size} tokens: in {fmt(d['tokens_in'])}")
        for k in ("headers_ms", "first_reasoning_ms", "first_token_ms", "total_ms", "after_first_token_ms",
                  "tokens_out", "reasoning_tokens", "gen_tokens_per_s"):
            print(f"   {k:<22} {fmt(d[k])}")
    for name in ("rpm", "tpm"):
        print(f"== {name} ==")
        for b in summary[name]:
            print(json.dumps({k: v for k, v in b.items() if k != "remaining_tokens_trajectory"}, default=str))
    print("== concurrency ==")
    for c in summary["concurrency"]:
        print(json.dumps(c, default=str))
    print("== daily request budget ==")
    print(json.dumps(summary["rpd_refill"], indent=1))
    (PROBE_DIR / "summary.json").write_text(json.dumps(summary, indent=1, default=str))


if __name__ == "__main__":
    main()

