    for c in chunks:
        assert c.n_tokens <= 200
        assert c.page_start <= c.page_end
        assert c.section != "References"
    by_section = {}
    for c in chunks:
        by_section.setdefault(c.section, []).append(c)
    assert "3.2.1 Scaled Dot-Product Attention" in by_section


