from __future__ import annotations

import time


class DeadlineExceeded(Exception):
    pass


class Deadline:
    """An absolute end time for one request; every stage asks how much time is left."""

    def __init__(self, seconds: float, clock=time.monotonic):
        self.clock = clock
        self.start = clock()
        self.at = self.start + seconds

    def remaining(self) -> float:
        return max(0.0, self.at - self.clock())

    def expired(self) -> bool:
        return self.clock() >= self.at

    def cap(self, seconds: float) -> float:
        """Timeout for a stage: its own cap, but never past the request deadline."""
        return min(seconds, self.remaining())

    def check(self, what: str):
        if self.expired():
            raise DeadlineExceeded(what)

"""Our own view of the provider's budget, so we wait or refuse *before* sending instead of
collecting 429s. Local accounting is primary; provider headers only correct it downwards,
because under concurrency they arrive out of order (R4)."""
from __future__ import annotations

import time
from dataclasses import dataclass

from app.providers.base import CallResult, RATE_LIMITED
from app.simulator.behavior import TokenBucket


class DailyBudgetExhausted(Exception):
    def __init__(self, kind: str, reset_s: float | None):
        super().__init__(kind)
        self.kind = kind
        self.reset_s = reset_s


@dataclass
class LimiterConfig:
    rpm: int
    tpm: int
    rpd: int
    tpd: int
    rpm_burst: int | None = None
    day_used_requests: int = 0
    day_used_tokens: int = 0


class ClientRateLimiter:
    def __init__(self, cfg: LimiterConfig, clock=time.monotonic):
        self.cfg = cfg
        self.clock = clock
        self.rpm = TokenBucket(cfg.rpm_burst or cfg.rpm, cfg.rpm / 60.0, clock)
        self.tpm = TokenBucket(cfg.tpm, cfg.tpm / 60.0, clock)
        self.day_requests = cfg.day_used_requests
        self.day_tokens = cfg.day_used_tokens
        self.day_remaining_requests_hdr: int | None = None
        self.day_reset_s: float | None = None
        self.daily_blocked: str | None = None
        self.cooldown_until = 0.0
        self.observed_tpm_limit: int | None = None

    # --- planning --------------------------------------------------------------------------
    def daily_check(self, est_tokens: int):
        if self.daily_blocked:
            raise DailyBudgetExhausted(self.daily_blocked, self.day_reset_s)
        req_left = self.cfg.rpd - self.day_requests
        if self.day_remaining_requests_hdr is not None:
            req_left = min(req_left, self.day_remaining_requests_hdr)
        if req_left < 1:
            raise DailyBudgetExhausted("RPD", self.day_reset_s)
        if self.day_tokens + est_tokens > self.cfg.tpd:
            raise DailyBudgetExhausted("TPD", None)

    def wait_needed(self, est_tokens: int) -> float:
        now = self.clock()
        return max(self.cooldown_until - now, self.rpm.seconds_until(1),
                   self.tpm.seconds_until(min(est_tokens, self.tpm.capacity)))

    def tpm_headroom(self) -> float:
        """Fraction of the per-minute token budget available right now (can be < 0)."""
        return self.tpm.available() / self.tpm.capacity

    def reserve(self, est_tokens: int):
        self.rpm.charge(1)
        self.tpm.charge(est_tokens)
        self.day_requests += 1
        self.day_tokens += est_tokens

    def settle(self, est_tokens: int, actual_tokens: int | None):
        """Replace the estimate with the real usage once the call is over."""
        if actual_tokens is None:
            return
        diff = actual_tokens - est_tokens
        self.tpm.charge(diff)
        self.day_tokens += diff

    # --- learning from responses ------------------------------------------------------------
    def observe(self, r: CallResult):
        rl = r.rate_limit
        if rl.limit_tokens_minute and rl.limit_tokens_minute != self.cfg.tpm:
            # the provider changed the per-minute token limit (e.g. halved): follow it
            self.observed_tpm_limit = rl.limit_tokens_minute
            self.cfg.tpm = rl.limit_tokens_minute
            self.tpm.capacity = rl.limit_tokens_minute
            self.tpm.per_second = rl.limit_tokens_minute / 60.0
        if rl.remaining_tokens_minute is not None:
            avail = self.tpm.available()
            if rl.remaining_tokens_minute < avail:
                self.tpm.charge(avail - rl.remaining_tokens_minute)
        if rl.remaining_requests_day is not None:
            self.day_remaining_requests_hdr = rl.remaining_requests_day
        if rl.reset_requests_day_s is not None:
            self.day_reset_s = rl.reset_requests_day_s
        if r.error_kind == RATE_LIMITED:
            if r.limit_kind in ("RPD", "TPD"):
                self.daily_blocked = r.limit_kind
            elif rl.retry_after_s:
                self.cooldown_until = max(self.cooldown_until, self.clock() + rl.retry_after_s)
            if r.limit_kind == "RPM":
                # our bucket was too optimistic: empty it so we pace at the refill rate
                self.rpm.charge(max(0.0, self.rpm.available()))

"""When to try a model call again. Bounded, jittered, deadline-aware, and limited by a shared
retry budget so that a provider-wide problem does not turn into a retry storm."""
from __future__ import annotations

import random
from dataclasses import dataclass, field

from app.providers.base import (CLIENT, CONNECTION, RATE_LIMITED, SERVER, TIMEOUT_AFTER_FIRST_TOKEN,
                                TIMEOUT_BEFORE_FIRST_TOKEN)

RETRYABLE = {RATE_LIMITED, SERVER, CONNECTION, TIMEOUT_BEFORE_FIRST_TOKEN, TIMEOUT_AFTER_FIRST_TOKEN}


@dataclass
class RetryDecision:
    retry: bool
    wait_s: float = 0.0
    reason: str = ""


@dataclass
class RetryPolicy:
    max_retries: int = 2
    base_s: float = 0.5
    cap_s: float = 8.0
    budget_ratio: float = 0.2       # each first attempt earns 0.2 retries; each retry spends 1
    budget_cap: float = 10.0
    naive: bool = False             # retry everything immediately (for the "retries made it worse" run)
    rng: random.Random = field(default_factory=lambda: random.Random(0))

    def __post_init__(self):
        self.budget = self.budget_cap
        self.retries_granted = 0
        self.retries_denied_budget = 0

    def first_attempt(self):
        self.budget = min(self.budget_cap, self.budget + self.budget_ratio)

    def decide(self, kind: str, limit_kind: str | None, retry_after_s: float | None,
               retries_so_far: int, remaining_s: float, expected_call_s: float) -> RetryDecision:
        if self.naive:
            if kind == CLIENT or retries_so_far >= 3:
                return RetryDecision(False, reason="naive: limit")
            self.retries_granted += 1
            return RetryDecision(True, 0.0, "naive: immediate")
        if kind not in RETRYABLE:
            return RetryDecision(False, reason=f"not retryable: {kind}")
        if kind == RATE_LIMITED and limit_kind in ("RPD", "TPD"):
            return RetryDecision(False, reason="daily limit: waiting cannot help")
        if retries_so_far >= self.max_retries:
            return RetryDecision(False, reason="max retries")
        wait = self.rng.uniform(0, min(self.cap_s, self.base_s * 2 ** retries_so_far))
        if retry_after_s:
            wait = retry_after_s + self.rng.uniform(0, 0.25)  # jitter so waiters do not wake together
        if wait + expected_call_s > remaining_s:
            return RetryDecision(False, wait, "deadline: no time for another attempt")
        if self.budget < 1:
            self.retries_denied_budget += 1
            return RetryDecision(False, wait, "retry budget exhausted")
        self.budget -= 1
        self.retries_granted += 1
        return RetryDecision(True, wait, f"retry {retries_so_far + 1} after {kind}")

"""Step 2 — understand the question, deterministically (no model call): validate it and detect
which papers it names, so retrieval can search each named paper and verification can check that
citations come from the paper that was asked about."""
from __future__ import annotations

import re
from dataclasses import dataclass, field

MIN_CHARS, MAX_CHARS = 3, 1000

STRONG_ALIASES = {
    "attention": [r"attention is all you need", r"\bvaswani", r"\b(original|base|big|vanilla) transformer",
                  r"transformer paper"],
    "moshi": [r"\bmoshi\b", r"\bmimi\b", r"\bhelium\b", r"inner monologue"],
    "hnet": [r"\bh-?net\b", r"dynamic chunking"],
}
# "Transformer" alone is ambiguous (Moshi and H-Net both use and compare against Transformers);
# it only points at the Attention paper when no other paper is named.
WEAK_ATTENTION = r"\btransformer"


@dataclass
class Analysis:
    question: str
    papers: list[str] = field(default_factory=list)

    @property
    def multi_paper(self) -> bool:
        return len(self.papers) > 1


def analyze(question: str) -> Analysis:
    q = " ".join((question or "").split())
    if len(q) < MIN_CHARS or len(q) > MAX_CHARS:
        raise ValueError(f"question must be {MIN_CHARS}-{MAX_CHARS} characters")
    low = q.lower()
    papers = [pid for pid, pats in STRONG_ALIASES.items() if any(re.search(p, low) for p in pats)]
    if not papers and re.search(WEAK_ATTENTION, low):
        papers = ["attention"]
    return Analysis(q, papers)

"""Step 5b — check the whole answer against the passages it cites, before anything is shown.

Per sentence: it must cite at least one passage we actually sent; every multi-digit or decimal
number in it must appear in a cited passage; enough of its content words must appear there; and
if the question names a paper, the citation must come from that paper. Rule-based on purpose:
an LLM judge would spend the same scarce tokens. It cannot judge paraphrased meaning."""
from __future__ import annotations

import re
from dataclasses import dataclass, field

from app.ingest.bm25 import tokenize
from app.pipeline.prompts import REFUSAL_TOKEN
from app.pipeline.retrieval import Passage

_CITE = re.compile(r"\[P(\d+)\]")
_ONLY_CITES = re.compile(r"^(\s*\[P\d+\]\s*)+[.]?$")
_SPLIT = re.compile(r"(?<=[.!?])\s+")
_NUMBER = re.compile(r"\d+(?:[.,]\d+)*")


@dataclass
class SentenceCheck:
    text: str
    cited: list[int]
    ok: bool
    reason: str = ""


@dataclass
class Verification:
    refused: bool
    sentences: list[SentenceCheck] = field(default_factory=list)

    @property
    def verified(self) -> list[SentenceCheck]:
        return [s for s in self.sentences if s.ok]

    @property
    def dropped(self) -> list[SentenceCheck]:
        return [s for s in self.sentences if not s.ok]

    @property
    def any_ok(self) -> bool:
        return bool(self.verified)

    def problems(self) -> list[str]:
        return [f"{s.reason}: \"{s.text[:120]}\"" for s in self.dropped]


def split_sentences(answer: str) -> list[str]:
    out: list[str] = []
    for piece in _SPLIT.split(answer.strip()):
        piece = piece.strip()
        if not piece:
            continue
        if out and _ONLY_CITES.match(piece):   # "... 64. [P2]" -> citation belongs to the sentence before
            out[-1] = f"{out[-1]} {piece}"
        else:
            out.append(piece)
    return out


def _numbers(text: str) -> set[str]:
    return {n.replace(",", "") for n in _NUMBER.findall(text) if len(n) >= 2}


def check_sentence(sentence: str, passages: list[Passage], named_papers: list[str],
                   min_overlap: float) -> SentenceCheck:
    cited = [int(x) for x in _CITE.findall(sentence)]
    claim = _CITE.sub("", sentence)
    if not cited:
        return SentenceCheck(sentence, cited, False, "no citation")
    if any(i < 1 or i > len(passages) for i in cited):
        return SentenceCheck(sentence, cited, False, "cites a passage that was not provided")
    cited_p = [passages[i - 1] for i in cited]
    if named_papers and not any(p.chunk.paper_id in named_papers for p in cited_p):
        return SentenceCheck(sentence, cited, False, "cites a different paper than the question names")
    source = " ".join(f"{p.citation()} {p.chunk.text}" for p in cited_p)
    source_numbers = {n.replace(",", "") for n in _NUMBER.findall(source)}
    missing = _numbers(claim) - source_numbers
    if missing:
        return SentenceCheck(sentence, cited, False, f"number not in cited passage: {sorted(missing)[0]}")
    words = set(tokenize(claim))
    if words:
        overlap = len(words & set(tokenize(source))) / len(words)
        if overlap < min_overlap:
            return SentenceCheck(sentence, cited, False, f"low overlap with cited passage ({overlap:.2f})")
    return SentenceCheck(sentence, cited, True)


def verify(answer: str, passages: list[Passage], named_papers: list[str] | None = None,
           min_overlap: float = 0.4) -> Verification:
    if REFUSAL_TOKEN in answer:
        return Verification(refused=True)
    return Verification(False, [check_sentence(s, passages, named_papers or [], min_overlap)
                                for s in split_sentences(answer)])


def render(v: Verification, passages: list[Passage]) -> tuple[str, list[str]]:
    """Verified sentences with [Pn] renumbered [1], [2]... by first use, plus the source list."""
    order: dict[int, int] = {}
    lines = []
    for s in v.verified:
        def sub(m):
            i = int(m.group(1))
            order.setdefault(i, len(order) + 1)
            return f"[{order[i]}]"
        lines.append(_CITE.sub(sub, s.text))
    text = " ".join(lines)
    if v.dropped:
        text += (f"\n\n({len(v.dropped)} statement(s) were removed because the cited passages did not "
                 f"support them.)")
    sources = [f"[{n}] {passages[i - 1].citation()}" for i, n in sorted(order.items(), key=lambda kv: kv[1])]
    return text, sources

